function unwrapString(value) {
  if (value === undefined || value === null) {
    return "";
  }

  const unwrapped = ObjC.unwrap(value);
  return unwrapped === undefined || unwrapped === null ? "" : String(unwrapped);
}

function isNil(value) {
  if (value === undefined || value === null) {
    return true;
  }

  const unwrapped = ObjC.unwrap(value);
  return unwrapped === undefined || unwrapped === null;
}

function applicationInfoForURL(urlString) {
  const url = $.NSURL.URLWithString(String(urlString || ""));
  if (isNil(url)) {
    return { name: "", bundleIdentifier: "" };
  }

  const appURL = $.NSWorkspace.sharedWorkspace.URLForApplicationToOpenURL(url);
  if (isNil(appURL)) {
    return { name: "", bundleIdentifier: "" };
  }

  const bundle = $.NSBundle.bundleWithURL(appURL);
  return {
    name: unwrapString($.NSFileManager.defaultManager.displayNameAtPath(appURL.path)),
    bundleIdentifier: isNil(bundle) ? "" : unwrapString(bundle.bundleIdentifier),
  };
}

function run(argv) {
  ObjC.import("AppKit");

  try {
    const request = JSON.parse(String(argv[0] || "{}"));
    const params = request.params || {};

    switch (request.action) {
      case "getApplicationNameForProtocol":
        return JSON.stringify({ name: applicationInfoForURL(params.url).name });
      case "isDefaultProtocolClient": {
        const protocol = String(params.protocol || "");
        const bundleIdentifier = String(params.bundleIdentifier || "");
        if (!protocol || !bundleIdentifier) {
          return JSON.stringify({ isDefault: false });
        }

        const info = applicationInfoForURL(protocol + ":");
        return JSON.stringify({
          isDefault: info.bundleIdentifier.toLowerCase() === bundleIdentifier.toLowerCase(),
        });
      }
      default:
        throw new Error("Unsupported app protocol-client action: " + request.action);
    }
  } catch (error) {
    return JSON.stringify({ error: String(error) });
  }
}

